#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include "kernel.h"
#include <string>

static void check_fp32_contiguous_cuda(
    const torch::Tensor& tensor, const std::string& name) {
    TORCH_CHECK(tensor.is_cuda(), name, " must be a CUDA tensor");
    TORCH_CHECK(
        tensor.dtype() == torch::kFloat32,
        name, " must have float32 dtype, got ", tensor.dtype());
    TORCH_CHECK(tensor.is_contiguous(), name, " must be contiguous");
}

// Destination-passing-style entry. Per definition.json:
//   query          : [batch_size, num_heads,    seq_len, head_dim=128]  fp32
//   key            : [batch_size, num_kv_heads, seq_len, head_dim=128]  fp32
//   cos            : [seq_len, head_dim]  fp32
//   sin            : [seq_len, head_dim]  fp32
//   query_rotated  : [batch_size, num_heads,    seq_len, head_dim]  fp32 (DPS)
//   key_rotated    : [batch_size, num_kv_heads, seq_len, head_dim]  fp32 (DPS)
//
// head_dim is pinned at 128. The same kernel runs twice: once for
// (query, query_rotated), once for (key, key_rotated). num_heads and
// num_kv_heads are workload-variable.
void run(
    const torch::Tensor& query,
    const torch::Tensor& key,
    const torch::Tensor& cos,
    const torch::Tensor& sin,
    torch::Tensor query_rotated,
    torch::Tensor key_rotated
) {
    TORCH_CHECK(query.dim() == 4, "query must be 4D [B, H, S, D]");
    TORCH_CHECK(key.dim() == 4, "key must be 4D [B, H_kv, S, D]");
    TORCH_CHECK(cos.dim() == 2, "cos must be 2D [S, D]");
    TORCH_CHECK(sin.dim() == 2, "sin must be 2D [S, D]");
    TORCH_CHECK(query_rotated.dim() == 4, "query_rotated must be 4D");
    TORCH_CHECK(key_rotated.dim() == 4, "key_rotated must be 4D");

    const int64_t head_dim = query.size(3);
    TORCH_CHECK(head_dim == 128,
                "head_dim must be 128 for problem_088, got ", head_dim);
    TORCH_CHECK(key.size(3) == head_dim,
                "key head_dim must match query head_dim");
    TORCH_CHECK(cos.size(1) == head_dim &&
                sin.size(1) == head_dim,
                "cos/sin last dim must be head_dim");
    TORCH_CHECK(query_rotated.sizes() == query.sizes(),
                "query_rotated shape must match query");
    TORCH_CHECK(key_rotated.sizes() == key.sizes(),
                "key_rotated shape must match key");
    TORCH_CHECK(cos.size(0) == query.size(2) &&
                sin.size(0) == query.size(2),
                "cos/sin seq_len must match query seq_len");
    TORCH_CHECK(key.size(2) == query.size(2),
                "key seq_len must match query seq_len");
    TORCH_CHECK(key.size(0) == query.size(0),
                "key batch_size must match query batch_size");

    check_fp32_contiguous_cuda(query, "query");
    check_fp32_contiguous_cuda(key, "key");
    check_fp32_contiguous_cuda(cos, "cos");
    check_fp32_contiguous_cuda(sin, "sin");
    check_fp32_contiguous_cuda(query_rotated, "query_rotated");
    check_fp32_contiguous_cuda(key_rotated, "key_rotated");

    cudaStream_t stream = at::cuda::getCurrentCUDAStream();
    problem_088_rotary_position_embedding_application_launcher(
        query, cos, sin, query_rotated, stream);
    problem_088_rotary_position_embedding_application_launcher(
        key, cos, sin, key_rotated, stream);
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def(
        "run", &run,
        "fp32 RoPE application: rotates query and key tensors by "
        "precomputed cos/sin tables. Two distinct DPS outputs "
        "(query_rotated, key_rotated). head_dim=128 pinned.");
}

#include "kernel.h"
#include <cuda_runtime.h>

// fp32 RoPE application: rotate query/key tensors by precomputed
// cos/sin tables.
//
//   rotate_half(x)[..., d] = -x[..., d + half_head_dim]  for d < half_head_dim
//                          =  x[..., d - half_head_dim]  for d >= half_head_dim
//   x_rotated[..., d]      = x[..., d] * cos[s, d] +
//                            rotate_half(x)[..., d] * sin[s, d]
//
// head_dim = 128 (pinned by the problem definition); half_head_dim =
// 64. One CTA per (b, h, s) row; BLOCK_THREADS = head_dim so each
// thread handles exactly one element of the row. The cos and sin
// tables are indexed by (s, d) only, so they're reused across all
// (B, H) row CTAs.

namespace {

constexpr int kHeadDim = 128;
constexpr int kHalfHeadDim = 64;
constexpr int kBlockThreads = kHeadDim;

__global__ void __launch_bounds__(kBlockThreads, 8)
problem_088_rope_kernel(
    const float* __restrict__ x,
    const float* __restrict__ cos_table,
    const float* __restrict__ sin_table,
    float* __restrict__ x_rotated,
    int num_heads,
    int seq_len) {

    // Grid layout: (s, num_heads, B). Each CTA handles one
    // (b, h, s) row of head_dim elements.
    const int s = blockIdx.x;
    const int h = blockIdx.y;
    const int b = blockIdx.z;
    const int d = threadIdx.x;

    const int row_offset =
        ((b * num_heads + h) * seq_len + s) * kHeadDim;
    const int cs_offset = s * kHeadDim;

    const float xv = x[row_offset + d];

    // rotate_half partner:
    //   d < 64  -> partner = d + 64, sign = -1
    //   d >= 64 -> partner = d - 64, sign = +1
    int partner;
    float partner_sign;
    if (d < kHalfHeadDim) {
        partner = d + kHalfHeadDim;
        partner_sign = -1.0f;
    } else {
        partner = d - kHalfHeadDim;
        partner_sign = 1.0f;
    }
    const float xv_partner = x[row_offset + partner];
    const float rh = partner_sign * xv_partner;

    const float cs = cos_table[cs_offset + d];
    const float sn = sin_table[cs_offset + d];

    x_rotated[row_offset + d] = xv * cs + rh * sn;
}

}  // namespace

void problem_088_rotary_position_embedding_application_launcher(
    const torch::Tensor& x,
    const torch::Tensor& cos_table,
    const torch::Tensor& sin_table,
    torch::Tensor& x_rotated,
    cudaStream_t stream) {

    // x is [B, num_heads_or_kv, S, head_dim] fp32.
    const int batch_size = static_cast<int>(x.size(0));
    const int num_heads = static_cast<int>(x.size(1));
    const int seq_len = static_cast<int>(x.size(2));

    dim3 grid(seq_len, num_heads, batch_size);
    dim3 block(kBlockThreads);

    problem_088_rope_kernel<<<grid, block, 0, stream>>>(
        x.data_ptr<float>(),
        cos_table.data_ptr<float>(),
        sin_table.data_ptr<float>(),
        x_rotated.data_ptr<float>(),
        num_heads,
        seq_len);
}

#pragma once

#ifndef PROBLEM_088_ROPE_APPLICATION_KERNEL_H
#define PROBLEM_088_ROPE_APPLICATION_KERNEL_H

#include <cuda_runtime.h>
#include <torch/extension.h>

// Host launcher for the fp32 RoPE-application kernel.
//
// For each input tensor `x` of shape [B, H, S, head_dim=128] fp32,
// compute:
//   rotate_half(x)[..., d]   = -x[..., d + 64]   for d in [0, 64)
//                            =  x[..., d - 64]   for d in [64, 128)
//   x_rotated[..., d]        = x[..., d] * cos[s, d] +
//                              rotate_half(x)[..., d] * sin[s, d]
//
// `cos` and `sin` are both [S, head_dim] fp32 and are reused across
// all (B, H) row CTAs. The launcher is parameterized on the input
// tensor and output destination so the DPS entry can call it twice
// (once for query→query_rotated, once for key→key_rotated).
void problem_088_rotary_position_embedding_application_launcher(
    const torch::Tensor& x,
    const torch::Tensor& cos_table,
    const torch::Tensor& sin_table,
    torch::Tensor& x_rotated,
    cudaStream_t stream);

#endif  // PROBLEM_088_ROPE_APPLICATION_KERNEL_H
